"""Embedded HTML interface for the Nashr hierarchical discovery console."""

NASHR_CONSOLE_HTML = '''<!DOCTYPE html>
<html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nashr Console</title><script src="https://cdn.tailwindcss.com"></script></head>
<body class="min-h-screen bg-slate-50 text-slate-900"><main class="mx-auto max-w-6xl px-4 py-8">
<header class="mb-8"><p class="text-sm font-semibold text-indigo-600">Nashr — Vertical Slice 2</p><h1 class="mt-1 text-3xl font-bold">خريطة الكتاب والمخزون التحريري</h1><p class="mt-2 text-sm text-slate-600">ارفع الكتاب، افحص محاوره، ثم اختر مادة حقيقية منه لتدخل مسار المسودة والمراجعة والنشر.</p></header>
<section class="rounded-2xl border bg-white p-5 shadow-sm"><div class="flex flex-col gap-4 sm:flex-row sm:items-end"><label class="flex-1"><span class="mb-2 block text-sm font-semibold">ملف PDF</span><input id="pdf-file" type="file" accept="application/pdf" class="block w-full rounded-xl border bg-slate-50 p-3 text-sm"></label><button id="upload-btn" class="rounded-xl bg-indigo-600 px-6 py-3 font-semibold text-white disabled:opacity-50">رفع وبناء خريطة الكتاب</button></div><div id="progress" class="mt-4 hidden text-sm text-slate-600"></div><div id="error" class="mt-4 hidden rounded-xl bg-red-50 p-3 text-sm text-red-700"></div></section>
<section id="book-section" class="mt-8 hidden"><div class="rounded-2xl border bg-white p-5 shadow-sm"><p class="text-xs font-semibold text-indigo-600">BOOK MAP</p><h2 id="book-title" class="mt-1 text-2xl font-bold"></h2><p id="book-description" class="mt-2 text-sm leading-7 text-slate-600"></p><div class="mt-4 flex gap-2 text-xs"><span id="topic-count" class="rounded-full bg-slate-100 px-3 py-1"></span><span id="material-count" class="rounded-full bg-slate-100 px-3 py-1"></span></div></div><div id="topics" class="mt-5 space-y-4"></div></section>
<section id="draft-section" class="mt-8 hidden rounded-2xl border border-indigo-200 bg-indigo-50 p-5"><p class="text-xs font-semibold text-indigo-700">EDITORIAL DRAFT</p><h2 class="mt-1 text-xl font-bold">مسودة المادة المختارة</h2><textarea id="draft-content" dir="rtl" class="mt-4 min-h-80 w-full rounded-xl border bg-white p-4 leading-7"></textarea><button id="publish-btn" class="mt-4 w-full rounded-xl bg-emerald-600 px-6 py-4 font-bold text-white disabled:opacity-50">نشر بعد المراجعة في تيليجرام</button></section>
<section id="success-section" class="mt-8 hidden rounded-2xl border border-emerald-200 bg-emerald-50 p-5"><h2 class="text-xl font-bold text-emerald-800">تم النشر بنجاح</h2><p class="mt-2 text-sm">Telegram message ID</p><code id="external-id" class="mt-1 block rounded bg-white p-2"></code></section>
</main><script>
const $=id=>document.getElementById(id); const state={publicationId:null};
function busy(v,msg){$('upload-btn').disabled=v;$('publish-btn').disabled=v;$('progress').classList.toggle('hidden',!v);$('progress').textContent=msg||'';}
function error(m){$('error').textContent=m;$('error').classList.remove('hidden');} function clearError(){$('error').classList.add('hidden');}
function esc(t){return (t??'').toString().replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
async function request(url,opt={}){const r=await fetch(url,opt);const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||'حدث خطأ غير متوقع.');return d;}
function renderBook(d){$('book-title').textContent=d.book.title;$('book-description').textContent=d.book.description;$('topic-count').textContent=d.topics.length+' محاور';$('material-count').textContent=d.count+' مواد';const html=d.topics.map(function(t){const mats=t.materials.map(function(m){return '<button data-id="'+esc(m.id)+'" class="material text-right rounded-xl border p-4 hover:border-indigo-400"><div class="flex justify-between gap-3"><strong class="text-sm">'+esc(m.title)+'</strong><span class="text-xs text-slate-400">'+esc(m.kind||'مادة')+'</span></div><p class="mt-2 line-clamp-3 text-xs leading-6 text-slate-600">'+esc(m.content)+'</p><p class="mt-2 text-xs text-slate-400">'+esc(m.source_reference||'مرجع غير محدد')+'</p></button>';}).join('');return '<article class="rounded-2xl border bg-white p-5 shadow-sm"><div class="flex items-start justify-between gap-4"><div><p class="text-xs text-slate-400">المحور '+t.position+'</p><h3 class="text-lg font-bold">'+esc(t.title)+'</h3><p class="mt-1 text-sm leading-6 text-slate-600">'+esc(t.description)+'</p></div><span class="rounded-full bg-indigo-50 px-3 py-1 text-xs text-indigo-700">'+t.materials.length+' مواد</span></div><div class="mt-4 grid gap-3">'+mats+'</div></article>';}).join('');$('topics').innerHTML=html;document.querySelectorAll('.material').forEach(function(b){b.onclick=function(){selectMaterial(b.dataset.id);};});$('book-section').classList.remove('hidden');}
async function selectMaterial(id){clearError();busy(true,'جاري إنشاء المسودة عبر المحرر الحالي...');try{const d=await request('/knowledge-units/'+id+'/draft',{method:'POST'});state.publicationId=d.id;$('draft-content').value=d.content||'';$('draft-section').classList.remove('hidden');$('draft-section').scrollIntoView({behavior:'smooth'});}catch(e){error(e.message);}finally{busy(false);}}
$('upload-btn').onclick=async function(){clearError();const file=$('pdf-file').files[0];if(!file)return error('اختر ملف PDF أولاً.');const form=new FormData();form.append('file',file);$('book-section').classList.add('hidden');$('draft-section').classList.add('hidden');$('success-section').classList.add('hidden');busy(true,'جاري حفظ PDF...');try{const s=await request('/sources',{method:'POST',body:form});busy(true,'Gemini يفهم الكتاب ويبني الخريطة ثم يكتشف المواد داخل كل محور...');const d=await request('/sources/'+s.id+'/extract',{method:'POST'});renderBook(d);}catch(e){error(e.message);}finally{busy(false);}};
$('publish-btn').onclick=async function(){if(!state.publicationId)return;clearError();busy(true,'جاري حفظ المراجعة والنشر في تيليجرام...');try{const d=await request('/publications/'+state.publicationId+'/publish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:$('draft-content').value})});if(d.status!=='PUBLISHED')throw Error(d.error_message||'تعذر تأكيد النشر.');$('external-id').textContent=d.external_id||'غير متاح';$('success-section').classList.remove('hidden');}catch(e){error(e.message);}finally{busy(false);}};
</script></body></html>'''
